INSERT INTO messages (message_id,case_id,posted_at,text_raw,text_clean,is_missing,views,forwards,reactions) VALUES (2482,6,'2024-03-22 14:06:49'::timestamptz,'مرحبا أنا ندى الحداد عمري 16 سنة أنا فقدت ماما وخلاتي وبنات خالاتي ولاد عمي وبنات عمي يعني فقدت كتير ناس واخوتي 2 متصاوبين واحد برجله بلاتين ومفتفتة والتاني كدامات وحاليا هما بالزرقاء والوضع كتير صعب عندهم اخوي مابنام الليل والنهار من كتر ما رجله بتجعه ومافي اكل ولا بيت ولا مي صار لها 6 شهور وانا حاليا بطالب بسحب بابا واخوتي ومرت خالي وابن خالتو الي فقد كل عائلته
