INSERT INTO message_translations (message_id,text_clean_en,names_en,location_en,dates_en) VALUES (318,'I received your greetings, peace be upon you and God''s mercy and blessings. Oh brother, how are you? I''m worried about you, I''m begging you, oh people, for God''s sake, if anyone knows anything about my family, on Sanaye'' Street, opposite Daghmash petrol station, Abu Fadi Al-Karm''s house, for God''s sake, anyone who knows anything or can find out, please tell us, my number is Omar Al-Safasafi 21266820152, my mother-in-law Hanan''s number is 972 59 513 2114',NULL,'The factory opposite Dugmash station',NULL);
INSERT INTO message_translations (message_id,text_clean_en,names_en,location_en,dates_en) VALUES (548,'If you please, for a month now, we have lost contact with my aunt, Al-Hajja Wadad Ibrahim Al-Saloul. My aunt was a resident at the Jabalia clinic, and after the army evacuated them from the clinic, we lost contact with her. We hope you can help us find her.','Widad Ibrahim Al-Saloul','Jabalia Clinic','For a month now');
INSERT INTO message_translations (message_id,text_clean_en,names_en,location_en,dates_en) VALUES (1633,'We have also received an appeal for the missing persons, my cousin''s son Ahmed Mohammed Kabbajeh and my cousin''s grandson Ziyad Wael Abu Ghalioun, who have been missing since Thursday, 8/2. They left from Deir al-Balah to Khan Yunis and we have no information about them. If anyone reaches them or knows anything about them, please contact me at 0599988858','Ahmad Muhammad Kabbaja; Ziyad Wael Abu Ghalioun','From Deir al-Balah to Khan Yunis','Thursday, February 8');
INSERT INTO message_translations (message_id,text_clean_en,names_en,location_en,dates_en) VALUES (1570,'An appeal for the loss of young Ahmed Jamal Nimer Al-Saho, 26 years old, from Rafah town, Al-Sentena street, who has special needs. He went missing in the first month of the war on Gaza. Whoever recognizes or finds him, please contact the number 0595157021 or via WhatsApp 970595157021','Ahmad Jamal Nimer Al-Sahow','Rafah City','The first month of the war on Gaza');
INSERT INTO message_translations (message_id,text_clean_en,names_en,location_en,dates_en) VALUES (568,'As-salamu alaykum, I wish you good health, an appeal for the loss of Al-Haj Nasr al-Din Hassan Abu Sakr, Abu Shadi, who was arrested by the Israeli occupation three days ago, on 7/10/2024, he was taken out of his house at the entrance of Al-Bureij camp and has been detained until now, we do not know any news about him and there is no contact with him at all, please anyone who has information about him contact us on the following numbers: 972 59 851 6358, 972 59 224 0351, 970 595 603 648, 059 940 0358, WhatsApp is active 24 hours: 972 59 566 4596','Nasr El-Din Hassan Abu Seker; Abu Shadi','Entrance of Al-Bureij camp','7 October 2024');
INSERT INTO message_translations (message_id,text_clean_en,names_en,location_en,dates_en) VALUES (474,'I''ve been informed that my brother Hatem Samir Frawana was lost during a bombing in the Thalatheeni area, opposite Al-Moroccani Street. I appeal to the Red Cross and I appeal to all brothers who were present to inform us about what happened, as one of the brothers transferred him to the Baptist Hospital, and after that, we lost any news about him since December 15th until today. We don''t know anything about him, so I wish everyone would inform us about any good news. May God protect everyone, have mercy on our martyrs, and heal our wounded. Anyone with any information, please contact me on 00971526679970 on WhatsApp or 00972567790004 on WhatsApp','Hatim Samir Furwana','Al-Thalatheeni area in front of Al-Moroccan Street','15-12');
INSERT INTO message_translations (message_id,text_clean_en,names_en,location_en,dates_en) VALUES (2482,'Hello, I''m Nada Al-Haddad, I''m 16 years old. I lost my mom, my aunt, my cousins, my uncle''s sons and daughters, meaning I lost a lot of people, and my two brothers are disabled, one has a platinum leg and is paralyzed, and the other has kidney problems. They are currently in Zarqa, and the situation is very difficult for them, my brother doesn''t sleep day or night because of the pain in his leg, and they have no food, no home, and no water. It''s been six months now, and I''m currently studying, my dad and brothers are trying to make a living, and my uncle''s wife and her son, who lost their whole family, we are now, me, Mahmoud, who lost his whole family, and Tita, who lost three daughters, asking the Red Cross to take them in, please','Mom; aunt; my aunts'' daughters; my cousin brothers; my cousin sisters','They have my brother, may God bring him back tonight',NULL);
INSERT INTO message_anonymized (message_id,clean,text_clean_anon) VALUES (318,NULL,'كما وصلني السلام عليكم ورحمه الله وبركاته ياخو كيف حالك طمني عنك مناشده ياجماعه بالله عليكم اي حد بيقدر يعرف اشي عن اهلي شارع الصناعه مقابل محطه دغمش للبترول دار ابو فادي الكرم بالله عليكم اللي بيقدر يعرف اشي او يوصل ل اشي يقولنا رقمي انا عمر الصفصافي PHONE_001 رقم حماتي حنان PHONE_002');
INSERT INTO message_anonymized (message_id,clean,text_clean_anon) VALUES (548,'وداد ابراهيم السلول','لو سمحتوا من فتره شهر فقدنا التواصل مع خالتي الحاجه PERSON_001 خالتي كانت مقيمه بعياده جباليا وبعد ما طلعهم الجيش من العياده فقدنا التواصل معها متمنين تساعدونا بايجادها');
INSERT INTO message_anonymized (message_id,clean,text_clean_anon) VALUES (1633,'احمد محمد كباجة زياد وائل غليون','كما وصل لنا مناشده المفقودين ابن خالتي احمد محمد كباجه وابن ابن خالي زياد وائل ابو غليون مفقودين من يوم الخميس 8 2 ذهبو من دير البلح الي خان يونس ولا نعلم عنهم اي شئ من يصل لهم او يعلم عنهم الرجاء التواصل معي PHONE_003');
INSERT INTO message_anonymized (message_id,clean,text_clean_anon) VALUES (1570,'احمد جمال نمر السحو','كما وصل مناشده فقدان الشاب PERSON_003 26 عام سكان رفح البلد شارع السنتيشن من ذوي الاحتياجات الخاصه تم فقدانه في الشهر الاول من الحرب علي غزه من يتعرف عليه او يعثر عليه الاتصال علي الرقم PHONE_004 او عبر الواتس اب PHONE_005');
INSERT INTO message_anonymized (message_id,clean,text_clean_anon) VALUES (585,NULL,'كما وصل لنا السلام عليكم لو سمحتم بدي نزل مناشده اختي نزحت من المغازي لرفح وم قدرت تاخد شي من غراضها م معهم حرامات ولا فرشات ولا اواعي ولا اي شي ومعهم اطفال برد كثير عليهم وم معهم مصاري يوفرو الاحتياجات اللازمه الي بقدر يساعدهم ربنا يجزيه كل خير PHONE_006');
INSERT INTO message_anonymized (message_id,clean,text_clean_anon) VALUES (568,'نصر الدين حسن سكر شادي','السلام عليكم يعطيكم العافيه مناشده لفقدان الحج PERSON_004 الذي تم اعتقالو من قبل الاحتلال الاسرائيلي قبل ثلاث ايام بتاريخ PHONE_007 تم اخراجه من بيته علي مدخل مخيم البريج واعتقاله لحد اللحظه لا نعلم اي خبر عنه ولا يوجد تواصل معه نهائيا الرجاء من اي شخص لديه معلومات بخصوصه الاتصال علي الارقام التاليه PHONE_008 واتس اب فعال علي مدار الساعه PHONE_009');
INSERT INTO message_anonymized (message_id,clean,text_clean_anon) VALUES (474,'حاتم سمير فروانة','كما يصلني تم فقدان اخي PERSON_005 اثناء قصفه بمنطقه الثلاثيني مقابل شارع المغربي اناشد الصليب الاحمر واناشد جميع الاخوه من كان بالمكان ابلاغنا بما حدث حيث قام احد الاخوه بنقله الي المستشفي المعمداني وبعدها تم فقدان اي خبر لحد الام منذو تاريخ 15 12الي حد اليوم لم نعلم اي شئ عنه فاتمني من الجميع ابلاغنا باي خير وسلم الله الجميع ورحم الله شهدائنا وشفي الله جرحانا واي شخص عنده اي معلومه ابلاغي PHONE_010 واتس اب او جوال PHONE_011واتس');
INSERT INTO message_anonymized (message_id,clean,text_clean_anon) VALUES (2482,'ماما خالة بنات خالاتي ولاد عمي بنات عمي','مرحبا انا ندي الحداد عمري 16 سنه انا فقدت ماما وخلاتي وبنات خالاتي ولاد عمي وبنات عمي يعني فقدت كتير ناس واخوتي 2 متصاوبين واحد برجله بلاتين ومفتفته والتاني كدامات وحاليا هما بالزرقاء والوضع كتير صعب عندهم اخوي مابنام الليل والنهار من كتر ما رجله بتجعه ومافي اكل ولا بيت ولا مي صار لها 6 شهور وانا حاليا بطالب بسحب بابا واخوتي ومرت خالي وابن خالتو الي فقد كل عائلته احنا الان انا ومحمود الي فقد كل عيلته وتيتا الي فقدت 3 بنات بطالب الصليب الاحمر لاصطحباهم رجاءءا');
INSERT INTO message_anonymized (message_id,clean,text_clean_anon) VALUES (2134,NULL,'مهم جدا الرجاء القراءه');
INSERT INTO message_anonymized (message_id,clean,text_clean_anon) VALUES (2121,NULL,'مرحبا تم فقدان هويه باسم محمد وحيد السعود واحنا نازحين في رفح اللي وجدها يتواصل معي علحساب ahmadkasam');
